function fragmentAt(root,index){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let text;while((text=walker.nextNode())){if(index<=text.length)return [text,index];index-=text.length;}return [root,root.childNodes.length];}
function portions(root,index){const [end,offset]=fragmentAt(root,index),range=document.createRange();range.setStart(root,0);range.setEnd(end,offset);const head=node('div');head.appendChild(range.cloneContents());range.setStart(end,offset);range.setEnd(root,root.childNodes.length);const tail=node('div');tail.appendChild(range.cloneContents());return [head.innerHTML,tail.innerHTML];}
async function paginate(){if(!doc||paginating||activePane!=='text')return;const editor=$('richEditor');if(editor.scrollHeight<=editor.clientHeight+2)return;paginating=true;clearTimeout(saveTimer);$('noteEditor').inert=true;const original=editor.innerHTML,current=doc,style=getComputedStyle(editor),measure=editor.cloneNode(false);measure.removeAttribute('id');measure.removeAttribute('contenteditable');measure.style.cssText='position:absolute;left:-20000px;top:0;width:674px;height:960px;overflow:hidden;visibility:hidden;padding:0;border:0;box-sizing:border-box;min-height:0';measure.style.font=style.font;measure.style.lineHeight='28px';measure.className='rich-editor';$('a4Sheet').appendChild(measure);
 try{let rest=cleanHtml(original),pages=[];while(rest&&pages.length<60){measure.innerHTML=rest;if(measure.scrollHeight<=measure.clientHeight+2){pages.push(rest);rest='';break;}const source=node('div');source.innerHTML=rest;const total=source.textContent.length;if(!total)throw new Error('L’elemento è più alto di una pagina. Riduci la tabella o il blocco.');let low=0,high=total;while(low<high){const mid=Math.ceil((low+high)/2),[head]=portions(source,mid);measure.innerHTML=head;if(measure.scrollHeight<=measure.clientHeight+2)low=mid;else high=mid-1;}if(low<1)throw new Error('Un blocco non entra in A4: riduci il contenuto o la dimensione dei caratteri.');const text=source.textContent,space=text.lastIndexOf(' ',low);if(space>low-70&&space>0)low=space+1;const [head,tail]=portions(source,low);if(tail===rest)throw new Error('Impossibile suddividere questo blocco.');pages.push(head);rest=tail;}
 if(rest)throw new Error('Testo molto lungo: incolla al massimo 60 pagine per volta.');if(pages.length<2)return;
 // Create the continuation first, so a failed save cannot erase the original text.
 let lastId=null;for(let i=1;i<pages.length;i++){const content=clone(DEFAULT);content.font=current.content.font;content.paper=current.content.paper;content.html=pages[i];content.images=Array.from(new Set(Array.from(pages[i].matchAll(/\/api\/tramonto\/images\/(\d+)/g),m=>Number(m[1]))));const created=await api('/api/tramonto/notes','POST',{notebook_id:current.notebook_id,title:current.title+' · continua '+(i+1),subject:current.subject,content,copy_images_from:current.id});lastId=created.id;}
 editor.innerHTML=pages[0];changed();if(!await saveDoc())throw new Error('Le pagine successive sono salvate; verifica il salvataggio della prima pagina.');await loadBooks();await openNoteLexical(lastId,true);$('richEditor').focus();const range=document.createRange();range.selectNodeContents($('richEditor'));range.collapse(false);const selection=getSelection();selection.removeAllRanges();selection.addRange(range);$('pageHint').textContent=pages.length+' pagine A4 salvate e numerate.';
 }catch(e){if(doc?.id===current.id){editor.innerHTML=original;changed();}error(e.message);}finally{measure.remove();paginating=false;$('noteEditor').inert=false;}}
$('splitPages').addEventListener('click',paginate);const schedulePages=()=>{clearTimeout(paginationTimer);paginationTimer=setTimeout(paginate,200);};$('richEditor').addEventListener('input',schedulePages);$('richEditor').addEventListener('paste',schedulePages);$('noteFont').addEventListener('change',schedulePages);
insert('pane-text','<div class="table-tools"><label>Righe <input id="tableRows" type="number" min="1" max="20" value="4"></label><label>Colonne <input id="tableCols" type="number" min="1" max="10" value="3"></label><button id="insertTable" class="secondary-button" type="button">+ Tabella</button><button id="addTableRow" class="secondary-button" type="button">+ Riga</button><button id="addTableCol" class="secondary-button" type="button">+ Colonna</button><label>Modello <select id="pageTemplate"><option value="">Scegli…</option><option value="lesson">Lezione</option><option value="cornell">Metodo Cornell</option><option value="lab">Relazione di laboratorio</option><option value="history">Analisi storica</option></select></label></div>');
