insert('componentForm','<div id="sourceParams" hidden><label>Forma<select id="sourceWave"><option value="sine">Sinusoide</option><option value="square">Quadra</option><option value="triangle">Triangolare</option></select></label><label>Frequenza Hz<input id="sourceFrequency" type="number" min="0.001" max="1000000000" value="1000" step="any"></label><label>Ampiezza V<input id="sourceAmplitude" type="number" min="0" max="1000000" value="1" step="any"></label><label>Offset V<input id="sourceOffset" type="number" value="0" step="any"></label><label>Duty %<input id="sourceDuty" type="number" min="1" max="99" value="50" step="any"></label></div><label id="switchParams" hidden><input id="switchClosed" type="checkbox"> Interruttore chiuso</label>');
