insert('pane-circuit','<section class="simulation-panel"><div class="panel-heading"><div><span class="eyebrow">LABORATORIO LOCALE</span><h3>Misura quello che hai disegnato.</h3></div><span id="spiceEngine" class="private-badge">ngspice</span></div><div class="simulation-settings"><label>Analisi<select id="spiceAnalysis"><option value="op">Punto di lavoro DC</option><option value="tran">Transitorio</option><option value="ac">Sweep AC</option><option value="dc">Sweep DC</option></select></label><label>Durata s<input id="spiceStop" type="number" value="0.01" min="0.000000001" max="100" step="any"></label><label>Campioni<input id="spiceSamples" type="number" value="500" min="20" max="2000"></label><label>Frequenza da Hz<input id="spiceStart" type="number" value="1" step="any"></label><label>Frequenza a Hz<input id="spiceEnd" type="number" value="100000" step="any"></label><label>Sweep DC da V<input id="spiceFrom" type="number" value="0" step="any"></label><label>Sweep DC a V<input id="spiceTo" type="number" value="5" step="any"></label></div><div class="tool-actions"><button id="simulateCircuit" class="primary-button">▶ Simula</button><button id="stopSimulation" class="secondary-button" disabled>■ Interrompi</button><button id="downloadNetlist" class="secondary-button">Netlist .cir</button><button id="downloadSpiceCsv" class="secondary-button" disabled>Risultati CSV</button><select id="circuitExample" aria-label="Esempio elettronico"><option value="">Carica esempio…</option><option value="divider">Divisore 5 V → 2,5 V</option><option value="rc">Filtro RC · sinusoide</option></select></div><p id="simulationStatus" role="status" class="tool-message"></p><div id="simulationResult"></div><p class="tool-note">Serve almeno una sorgente e una massa. Per misurare un nodo aggiungi una sonda. Amperometri in serie, voltmetri e oscilloscopi in parallelo. I modelli di transistor, opamp e porte sono semplificati; non rappresentano un componente commerciale.</p></section>');
function spiceOptions(){return{analysis:$('spiceAnalysis').value,stop:Number($('spiceStop').value),samples:Number($('spiceSamples').value),start:Number($('spiceStart').value),end:Number($('spiceEnd').value),dc_start:Number($('spiceFrom').value),dc_end:Number($('spiceTo').value),points:30};}
let lastSimulation=null;
async function poll(){if(!job)return;try{const result=await api('/api/tramonto/simulations/'+job);if(!result.done){pollTimer=setTimeout(poll,650);return;}job=null;$('simulateCircuit').disabled=false;$('stopSimulation').disabled=true;if(result.result&&!result.result.error){lastSimulation=result.result;renderSimulation(result.result);$('simulationStatus').textContent='Simulazione completata · '+result.result.engine;$('downloadSpiceCsv').disabled=false;}else $('simulationStatus').textContent=result.result?.error||'Simulazione interrotta.';}catch(e){job=null;$('simulateCircuit').disabled=false;$('stopSimulation').disabled=true;$('simulationStatus').textContent=e.message;}}
$('simulateCircuit').addEventListener('click',async()=>{try{if(!doc||!await saveDoc())return;$('simulateCircuit').disabled=true;const result=await api('/api/tramonto/simulations','POST',{note_id:doc.id,options:spiceOptions()});job=result.job_id;$('stopSimulation').disabled=false;$('simulationStatus').textContent='Simulazione in corso…';poll();}catch(e){$('simulateCircuit').disabled=false;$('simulationStatus').textContent=e.message;}});
$('stopSimulation').addEventListener('click',async()=>{if(job)await api('/api/tramonto/simulations/'+job+'/cancel','POST',{});clearTimeout(pollTimer);job=null;$('stopSimulation').disabled=true;$('simulateCircuit').disabled=false;$('simulationStatus').textContent='Simulazione interrotta.';});
function download(value,type,name){const url=URL.createObjectURL(new Blob([value],{type})),a=node('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
