insert('pane-network','<div class="network-heading"><span class="eyebrow">SISTEMI E RETI</span><h3>Un pacchetto, un percorso.</h3><p class="tool-note">Topologie e simboli di rete ispirati ai laboratori Cisco. Simulatore didattico IPv4 locale: non esegue IOS e non invia pacchetti sulla rete reale.</p></div><div id="networkPalette" class="component-palette"></div><div class="tool-actions"><button id="networkSelect" class="secondary-button">Sposta</button><button id="networkWire" class="secondary-button">Collega</button><select id="networkCable" aria-label="Tipo di collegamento"><option value="ethernet">Ethernet</option><option value="fiber">Fibra</option><option value="serial">Seriale</option><option value="wifi">Wi-Fi</option></select><button id="networkDelete" class="secondary-button">Elimina selezione</button><button id="networkUndo" class="secondary-button">Annulla</button><button id="networkExample" class="secondary-button">Esempio LAN</button><button id="exportNetwork" class="secondary-button">SVG</button></div><svg id="networkSvg" viewBox="0 0 1000 640" role="application" aria-label="Editor di topologie di rete" tabindex="0"></svg><form id="networkForm" class="component-properties" hidden><label>Nome<input id="networkName" maxlength="60"></label><label>IPv4 / prefisso<input id="networkIp" placeholder="192.168.1.2/24" maxlength="50"></label><label>Gateway<input id="networkGateway" placeholder="192.168.1.1" maxlength="50"></label><label>VLAN<input id="networkVlan" type="number" min="1" max="4094" value="1"></label><label>Interfacce router (CIDR, una per riga)<textarea id="networkInterfaces" maxlength="500" placeholder="192.168.1.1/24"></textarea></label><label><input id="networkEnabled" type="checkbox" checked> Dispositivo / collegamento attivo</label><button class="secondary-button">Salva dispositivo</button></form><div class="simulation-panel"><h3>Verifica la comunicazione.</h3><div class="tool-actions"><label>Da<select id="pingSource"></select></label><label>A<select id="pingTarget"></select></label><button id="networkPing" class="primary-button">▶ Ping simulato</button></div><p id="networkResult" role="status" class="tool-message"></p><form id="networkCli"><label>Console didattica<input id="networkCommand" maxlength="150" placeholder="show ip interface brief / show vlan brief / ping 192.168.1.2"></label><button class="secondary-button">Esegui</button></form><pre id="networkConsole" class="network-console"></pre></div><div class="math-section"><h3>Indirizzi, senza confondersi.</h3><div class="tool-actions"><label>IPv4 / CIDR<input id="subnetInput" value="192.168.1.20/24"></label><button id="subnetCalculate" class="secondary-button">Calcola sottorete</button></div><p id="subnetResult" class="tool-message" role="status"></p></div>');
