function resetImage(){selectedImage=null;draggedImage=null;savedRange=null;selectionBox.hidden=true;if($('imageInspector'))$('imageInspector').hidden=true;}
function positionImage(){if(!selectedImage?.isConnected){selectionBox.hidden=true;return;}const sheet=$('a4Sheet'),rect=selectedImage.getBoundingClientRect(),base=sheet.getBoundingClientRect(),scale=base.width/794;selectionBox.hidden=activePane!=='text';selectionBox.style.left=((rect.left-base.left)/scale)+'px';selectionBox.style.top=((rect.top-base.top)/scale)+'px';selectionBox.style.width=(rect.width/scale)+'px';selectionBox.style.height=(rect.height/scale)+'px';}
function selectImage(image){selectedImage=image;const inspector=$('imageInspector');if(!inspector)return;inspector.hidden=!image;selectionBox.hidden=!image;if(image){$('inlineImageWidth').value=image.width||450;$('inlineImageLayout').value=image.dataset.layout||'inline';positionImage();}}
let resizing=null;
resizeHandle.addEventListener('pointerdown',event=>{if(!selectedImage)return;event.preventDefault();event.stopPropagation();resizing={x:event.clientX,width:selectedImage.width,scale:$('a4Sheet').getBoundingClientRect().width/794};resizeHandle.setPointerCapture(event.pointerId);});
