function moveImage(direction){if(!selectedImage?.isConnected)return;const editor=$('richEditor');let block=selectedImage;while(block.parentElement&&block.parentElement!==editor)block=block.parentElement;const neighbor=direction<0?block.previousElementSibling:block.nextElementSibling;if(neighbor){if(direction<0)editor.insertBefore(selectedImage,neighbor);else editor.insertBefore(selectedImage,neighbor.nextSibling);}else if(direction<0)editor.prepend(selectedImage);else editor.appendChild(selectedImage);changed();positionImage();schedulePages();}
