async function insertFile(file,width=450){if(!doc||uploading)return false;const current=doc;if(file.size>8*1024*1024){error('Massimo 8 MB per immagine.');return;}if(current.content.images.length>=30){error('Massimo trenta immagini per pagina.');return;}if(!await saveDoc())return;uploading=true;$('saveStatus').textContent='Importazione immagine…';try{const response=await fetch('/api/tramonto/notes/'+current.id+'/images',{method:'POST',credentials:'same-origin',headers:{'Content-Type':file.type||'image/png','X-CSRF-Token':csrf,'X-Image-Name':encodeURIComponent((file.name||'Laboratorio.png').slice(0,180))},body:file}),data=await response.json();if(!response.ok)throw Error(data.error||'Immagine non valida.');current.content.images.push(data.id);if(current===doc){insertExisting(data.id,width);renderImages();return true;}return false;}catch(e){error(e.message);}finally{uploading=false;if(current===doc)await saveDoc();}}
